// ── Bevel: one indexed target or one open boundary loop, host-owned session ───
// The cart owns only popup values. Stable topology identity, preview installation,
// part/material/UV provenance, exact cancel, and the one-entry journal transaction
// stay behind this boundary.
pub const BevelSessionKind = enum { vertex, edge, boundary, face_polygon };
pub const BevelSession = struct {
    kind: z3d.BevelSessionKind,
    original_mode: mesh_edit.Mode,
    selection_index: u32,
    target: ?indexed_edit_mesh.BevelTarget,
    boundary_loop: ?[]u32,
    boundary_selection: ?[]mesh_edit.Edge,
    polygon_faces: ?[]u32,
    polygon_source_face: ?u32,
    // Mirror (req_3797): the target's resolved twins, one slot per plane subset —
    // every preview/commit bevels them at the same width in the same journal entry.
    twin_targets: [7]?indexed_edit_mesh.BevelTarget = [_]?indexed_edit_mesh.BevelTarget{null} ** 7,
    max_width: f32,
    base_mesh: indexed_edit_mesh.Mesh,
    last_mesh: ?indexed_edit_mesh.Mesh,
    base_paint_layout_stale: bool,
    base_groups: ?[]u32,
    base_colors: []u8,
    base_face_part: ?[]u32,
    last_face_part: ?[]u32,
    part_count: u32,
    snap: ?z3d.JournalEntry,
    last_center_triangle: ?u32 = null,
    last_preview_ok: bool = false,
    last_reason: ?[]const u8 = null,
};

pub fn bevelFree() void {
    var session = z3d.g_bevel orelse return;
    session.base_mesh.deinit();
    if (session.last_mesh) |*mesh| mesh.deinit();
    if (session.base_groups) |groups| std.heap.c_allocator.free(groups);
    std.heap.c_allocator.free(session.base_colors);
    if (session.base_face_part) |parts| std.heap.c_allocator.free(parts);
    if (session.last_face_part) |parts| std.heap.c_allocator.free(parts);
    if (session.boundary_loop) |loop| std.heap.c_allocator.free(loop);
    if (session.boundary_selection) |edges| std.heap.c_allocator.free(edges);
    if (session.polygon_faces) |faces| std.heap.c_allocator.free(faces);
    z3d.journalDiscard(&session.snap);
    z3d.g_bevel = null;
}

pub const BevelInfo = struct {
    kind: z3d.BevelSessionKind,
    default_width: f32,
    minimum_width: f32,
    max_width: f32,
    sides_before: u32 = 0,
    default_target_sides: u32 = 0,
    minimum_target_sides: u32 = 0,
    maximum_target_sides: u32 = 0,
};

/// Capture one vertex/sharp edge, one complete selected open-boundary edge loop,
/// or one filled authored face and resolve it into stable indexed identity.
/// Boundary loops and filled faces expose target-side ranges; the latter rebuilds
/// as a welded N-gon center ready for immediate face extrusion.
pub fn meshBevelBegin() ?z3d.BevelInfo {
    z3d.g_topo_refusal = "";
    if (z3d.g_lc != null) {
        z3d.topoRefuse("a loop cut session is still open — commit or cancel it first");
        return null;
    }
    if (z3d.g_bevel != null) _ = z3d.meshBevelEnd(false);
    if (!model_paint.hasTarget()) {
        z3d.topoRefuse("no paint target is bound to this model");
        return null;
    }
    const original_mode = mesh_edit.mode();
    if (original_mode != .vertex and original_mode != .edge and original_mode != .face) {
        z3d.topoRefuse("bevel needs vertex, edge, or face select mode");
        return null;
    }
    const verts = z3d.g_edit_verts orelse {
        z3d.topoRefuse("no editable mesh is resident");
        return null;
    };
    const tri_count = z3d.g_edit_count / 3;
    // No paint-layout gate here either (req_4114): a bevel/chamfer is topology work, and
    // demanding a current UV atlas to perform it inverts the authoring order outright.
    if (tri_count == 0) {
        z3d.topoRefuse("the mesh has no triangles");
        return null;
    }

    var groups: ?[]u32 = null;
    if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) {
        const rows = std.heap.c_allocator.alloc(u32, tri_count) catch return null;
        var triangle: u32 = 0;
        while (triangle < tri_count) : (triangle += 1) rows[triangle] = model_source.faceGroupOf(triangle);
        groups = rows;
    }
    var ownership_adopted = false;
    defer if (!ownership_adopted) {
        if (groups) |rows| std.heap.c_allocator.free(rows);
    };

    const base_colors = z3d.collectCurrentFaceColors() orelse return null;
    defer if (!ownership_adopted) std.heap.c_allocator.free(base_colors);
    if (base_colors.len != @as(usize, tri_count) * 4) return null;
    const base_face_part = z3d.capturePartOfFaces();
    defer if (!ownership_adopted) {
        if (base_face_part) |parts| std.heap.c_allocator.free(parts);
    };

    const groups_arg: ?[]const u32 = if (groups) |rows| rows else null;
    const parts_arg: ?[]const u32 = if (base_face_part) |parts| parts else null;
    var base_mesh = z3d.cloneIndexedEditMeshOrImport(
        verts,
        tri_count,
        groups_arg,
        parts_arg,
        model_source.faceMaterials(),
    ) orelse return null;
    var mesh_adopted = false;
    defer if (!mesh_adopted) base_mesh.deinit();

    var selection_index: u32 = 0;
    var target: ?indexed_edit_mesh.BevelTarget = null;
    var boundary_loop: ?[]u32 = null;
    var boundary_selection: ?[]mesh_edit.Edge = null;
    var polygon_faces: ?[]u32 = null;
    var polygon_source_face: ?u32 = null;
    var boundary_info: ?indexed_edit_mesh.BoundaryChamferSelection = null;
    var polygon_info: ?indexed_edit_mesh.FacePolygonSelection = null;
    defer if (!ownership_adopted) {
        if (boundary_loop) |loop| std.heap.c_allocator.free(loop);
        if (boundary_selection) |edges| std.heap.c_allocator.free(edges);
        if (polygon_faces) |faces| std.heap.c_allocator.free(faces);
    };
    var kind: z3d.BevelSessionKind = undefined;
    var shared_max_width: f32 = undefined;
    switch (original_mode) {
        .vertex => vertex_target: {
            const vertex = mesh_edit.selectedVertexIndexPub() orelse return null;
            const part = mesh_edit.selectedVertexPartPub() orelse return null;
            selection_index = vertex;
            const resolved = base_mesh.resolveBevelVertex(mesh_edit.vertPosPub(vertex), part) orelse return null;
            target = resolved.target;
            kind = .vertex;
            shared_max_width = resolved.max_width;
            break :vertex_target;
        },
        .edge => edge_target: {
            const selected_count = mesh_edit.selectedEdgeCountPub();
            if (selected_count == 1) {
                const edge_index = mesh_edit.selectedEdgeIndexPub() orelse return null;
                if (!mesh_edit.edgeInScopePub(edge_index)) return null;
                const part = mesh_edit.selectedEdgePartPub() orelse return null;
                const endpoints = mesh_edit.edgeEndpointsPub(edge_index);
                selection_index = edge_index;
                const resolved = base_mesh.resolveBevelEdge(
                    mesh_edit.vertPosPub(endpoints[0]),
                    mesh_edit.vertPosPub(endpoints[1]),
                    part,
                ) orelse return null;
                target = resolved.target;
                kind = .edge;
                shared_max_width = resolved.max_width;
                break :edge_target;
            }
            if (selected_count < indexed_edit_mesh.BoundaryChamferTuning.minimum_sides) return null;
            const selected = std.heap.c_allocator.alloc(mesh_edit.Edge, selected_count) catch return null;
            boundary_selection = selected;
            if (mesh_edit.selectedEdgesPub(selected) != selected_count) return null;
            const part = mesh_edit.selectedEdgesCommonPartPub() orelse return null;
            const edge_positions = std.heap.c_allocator.alloc([2]indexed_edit_mesh.Vec3, selected_count) catch return null;
            defer std.heap.c_allocator.free(edge_positions);
            for (selected, 0..) |edge, index| edge_positions[index] = .{
                mesh_edit.vertPosPub(edge[0]), mesh_edit.vertPosPub(edge[1]),
            };
            const loop = std.heap.c_allocator.alloc(u32, selected_count) catch return null;
            boundary_loop = loop;
            const resolved = base_mesh.resolveBoundaryChamfer(edge_positions, part, loop) orelse return null;
            boundary_info = resolved;
            kind = .boundary;
            shared_max_width = resolved.max_width;
        },
        .face => face_target: {
            const selected_mask = std.heap.c_allocator.alloc(bool, tri_count) catch {
                z3d.topoRefuse("out of memory building the face selection mask");
                return null;
            };
            defer std.heap.c_allocator.free(selected_mask);
            if (mesh_edit.buildDeleteMask(selected_mask) == 0) {
                z3d.topoRefuse("no faces are selected");
                return null;
            }
            const resolved = base_mesh.resolveFacePolygon(selected_mask) orelse {
                const resolved_faces = indexed_edit_mesh.Mesh.last_face_polygon_faces;
                z3d.g_topo_refusal = std.fmt.bufPrint(
                    &z3d.g_topo_refusal_buf,
                    "Face to N-gon refused: {s} (selection resolved to {d} authored face(s))",
                    .{ indexed_edit_mesh.Mesh.last_face_polygon_stage, resolved_faces },
                ) catch "Face to N-gon needs exactly one whole authored face";
                return null;
            };
            polygon_info = resolved;
            polygon_source_face = resolved.face_id;
            selection_index = resolved.selection_triangle;

            var complete_mask = selected_mask;
            var mirrored_mask: ?[]bool = null;
            defer if (mirrored_mask) |rows| std.heap.c_allocator.free(rows);
            if (mesh_edit.mirrorMask() != 0) {
                const rows = std.heap.c_allocator.dupe(bool, selected_mask) catch return null;
                mirrored_mask = rows;
                z3d.extendFaceMaskWithMirrorTwins(verts, tri_count, rows);
                complete_mask = rows;
            }
            var selected_faces = std.ArrayListUnmanaged(u32).empty;
            defer selected_faces.deinit(std.heap.c_allocator);
            if (!(base_mesh.selectedFaceIds(complete_mask, &selected_faces) catch return null) or selected_faces.items.len == 0) return null;
            shared_max_width = resolved.max_width;
            for (selected_faces.items) |face_id| {
                const limit = base_mesh.facePolygonLimit(face_id) orelse return null;
                shared_max_width = @min(shared_max_width, limit);
            }
            polygon_faces = std.heap.c_allocator.dupe(u32, selected_faces.items) catch return null;
            kind = .face_polygon;
            break :face_target;
        },
        else => return null,
    }
    // Mirror (req_3797): resolve the target's twin per enabled plane subset against
    // the same base. A twin that resolves joins every preview/commit; its max width
    // tightens the shared clamp so one slider drives both sides.
    var twin_targets = [_]?indexed_edit_mesh.BevelTarget{null} ** 7;
    if (kind != .boundary and mesh_edit.mirrorMask() != 0) {
        var subset: u8 = 1;
        while (subset <= 7) : (subset += 1) {
            const twin_resolved: ?indexed_edit_mesh.BevelSelection = switch (original_mode) {
                .vertex => vertex_twin: {
                    const twin = mesh_edit.mirrorTwinOfVertPub(selection_index, subset) orelse break :vertex_twin null;
                    const twin_part = mesh_edit.vertPartPub(twin) orelse break :vertex_twin null;
                    break :vertex_twin base_mesh.resolveBevelVertex(mesh_edit.vertPosPub(twin), twin_part);
                },
                .edge => edge_twin: {
                    const endpoints = mesh_edit.edgeEndpointsPub(selection_index);
                    const t0 = mesh_edit.mirrorTwinOfVertPub(endpoints[0], subset) orelse break :edge_twin null;
                    const t1 = mesh_edit.mirrorTwinOfVertPub(endpoints[1], subset) orelse break :edge_twin null;
                    const same_edge = (t0 == endpoints[0] and t1 == endpoints[1]) or (t0 == endpoints[1] and t1 == endpoints[0]);
                    if (same_edge or !mesh_edit.hasEdgeBetweenPub(t0, t1)) break :edge_twin null;
                    const twin_part = mesh_edit.vertPartPub(t0) orelse break :edge_twin null;
                    if ((mesh_edit.vertPartPub(t1) orelse break :edge_twin null) != twin_part) break :edge_twin null;
                    break :edge_twin base_mesh.resolveBevelEdge(mesh_edit.vertPosPub(t0), mesh_edit.vertPosPub(t1), twin_part);
                },
                else => null,
            };
            const twin_selection = twin_resolved orelse continue;
            const target_kind: z3d.BevelSessionKind = switch (std.meta.activeTag(twin_selection.target)) {
                .vertex => .vertex,
                .edge => .edge,
            };
            if (target_kind != kind) continue;
            twin_targets[subset - 1] = twin_selection.target;
            shared_max_width = @min(shared_max_width, twin_selection.max_width);
        }
    }
    const minimum_width = switch (kind) {
        .boundary => indexed_edit_mesh.BoundaryChamferTuning.minimum_width_m,
        .face_polygon => indexed_edit_mesh.FacePolygonTuning.minimum_width_m,
        else => indexed_edit_mesh.BevelTuning.minimum_width_m,
    };
    const default_width = std.math.clamp(
        switch (kind) {
            .boundary => indexed_edit_mesh.BoundaryChamferTuning.default_width_m,
            .face_polygon => polygon_info.?.default_width,
            else => indexed_edit_mesh.BevelTuning.default_width_m,
        },
        minimum_width,
        shared_max_width,
    );
    const label = switch (kind) {
        .edge => "bevel edge",
        .vertex => "bevel vertex",
        .boundary => "chamfer boundary",
        .face_polygon => "face to n-gon",
    };
    z3d.g_bevel = .{
        .kind = kind,
        .original_mode = original_mode,
        .selection_index = selection_index,
        .target = target,
        .boundary_loop = boundary_loop,
        .boundary_selection = boundary_selection,
        .polygon_faces = polygon_faces,
        .polygon_source_face = polygon_source_face,
        .twin_targets = twin_targets,
        .max_width = shared_max_width,
        .base_mesh = base_mesh,
        .last_mesh = null,
        .base_paint_layout_stale = z3d.g_paint_layout_stale,
        .base_groups = groups,
        .base_colors = base_colors,
        .base_face_part = base_face_part,
        .last_face_part = null,
        .part_count = z3d.hostPartCount(),
        .snap = z3d.journalSnapshotCurrent(label),
    };
    mesh_adopted = true;
    ownership_adopted = true;
    return .{
        .kind = kind,
        .default_width = default_width,
        .minimum_width = minimum_width,
        .max_width = shared_max_width,
        .sides_before = if (boundary_info) |resolved| resolved.sides_before else if (polygon_info) |resolved| resolved.sides_before else 0,
        .default_target_sides = if (boundary_info) |resolved| resolved.default_target_sides else if (polygon_info) |resolved| resolved.default_target_sides else 0,
        .minimum_target_sides = if (boundary_info) |resolved| resolved.minimum_target_sides else if (polygon_info) |resolved| resolved.minimum_target_sides else 0,
        .maximum_target_sides = if (boundary_info) |resolved| resolved.maximum_target_sides else if (polygon_info) |resolved| resolved.maximum_target_sides else 0,
    };
}

/// Rebuild a bevel preview from the captured indexed base. Preview never touches the
/// undo stack; all new render triangles inherit paint/material/part provenance through
/// the indexed lowering map.
pub fn meshBevelPreview(width_raw: f32, target_sides: u32) bool {
    const session: *z3d.BevelSession = if (z3d.g_bevel) |*active| active else return false;
    session.last_preview_ok = false;
    session.last_reason = switch (session.kind) {
        .edge => "This edge cannot produce a durable bevel at that width",
        .vertex => "This corner cannot produce a durable bevel at that width",
        .boundary => "This opening cannot produce that target side count at this width",
        .face_polygon => "This face cannot produce that welded center side count at this ring width",
    };
    const minimum_width = switch (session.kind) {
        .boundary => indexed_edit_mesh.BoundaryChamferTuning.minimum_width_m,
        .face_polygon => indexed_edit_mesh.FacePolygonTuning.minimum_width_m,
        else => indexed_edit_mesh.BevelTuning.minimum_width_m,
    };
    const width = std.math.clamp(
        width_raw,
        minimum_width,
        session.max_width,
    );
    var preview = session.base_mesh.clone() catch return false;
    defer preview.deinit();
    var center_face_id: ?u32 = null;
    const changed: bool = switch (session.kind) {
        .edge, .vertex => preview.bevel(session.target orelse return false, width) catch return false,
        .boundary => preview.chamferBoundary(session.boundary_loop orelse return false, width, target_sides) catch return false,
        .face_polygon => polygonize: {
            const faces = session.polygon_faces orelse return false;
            if (faces.len == 0) return false;
            for (faces) |face_id| {
                const center = (preview.polygonizeFace(face_id, width, target_sides) catch return false) orelse return false;
                if (face_id == session.polygon_source_face.?) center_face_id = center;
            }
            break :polygonize center_face_id != null;
        },
    };
    if (!changed) return false;
    // Mirror (req_3797): every resolved twin bevels at the same width in this preview
    // — a twin that stops beveling refuses the whole preview, never half a chamfer.
    for (session.twin_targets) |twin_opt| {
        const twin = twin_opt orelse continue;
        if (!(preview.bevel(twin, width) catch return false)) return false;
    }

    var lowered = preview.lower() catch return false;
    defer lowered.deinit();
    var center_triangle: ?u32 = null;
    if (center_face_id) |wanted_face| {
        for (lowered.face_ids, 0..) |face_id, triangle| {
            if (face_id != wanted_face) continue;
            center_triangle = @intCast(triangle);
            break;
        }
        if (center_triangle == null) return false;
    }
    // Fresh bevel/chamfer faces do not own UV space in the existing paint
    // contract. Their generated 0..1 square used to sample the entire authored
    // atlas during preview, presenting random image fragments as the new corner
    // surfaces. Keep every pre-existing triangle's interpolated UVs exact, while
    // the newly appended face ids share one neutral gutter texel until Remake
    // Paint Atlas gives the changed topology a real layout.
    if (model_paint.hasAuthoredAtlas()) {
        const neutral_uv = model_paint.reserveNeutralPlaceholderUv() orelse return false;
        const first_generated_face: u32 = @intCast(session.base_mesh.faces.items.len);
        if (!lowered.pointFreshFacesAtUv(first_generated_face, neutral_uv)) return false;
    }
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, lowered.tri_count) * 4) catch return false;
    defer std.heap.c_allocator.free(colors);
    if (!mesh_edit.inheritFaceRgba(session.base_colors, lowered.source_triangles, colors)) return false;

    if (session.last_face_part) |parts| std.heap.c_allocator.free(parts);
    session.last_face_part = null;
    if (session.base_face_part != null) {
        session.last_face_part = std.heap.c_allocator.dupe(u32, lowered.parts) catch return false;
    }
    const install_groups: ?[]const u32 = if (session.base_groups != null) lowered.groups else null;
    if (!z3d.lcInstallLowered(
        lowered.positions,
        lowered.uvs,
        lowered.tri_count,
        install_groups,
        lowered.materials,
        lowered.semantic_regions,
        lowered.semantic_instances,
        colors,
        z3d.flattenedLogicalRows(lowered.triangle_vertices),
        @intCast(preview.vertices.items.len),
    )) return false;
    if (session.kind == .face_polygon) {
        mesh_edit.setMode(.face);
        mesh_edit.clearSelection();
        if (!mesh_edit.selectFaceByIndex(center_triangle.?, false)) return false;
    } else {
        mesh_edit.setMode(session.original_mode);
    }
    if (session.last_mesh) |*mesh| mesh.deinit();
    session.last_mesh = preview;
    preview = .{ .allocator = std.heap.c_allocator };
    session.last_center_triangle = center_triangle;
    session.last_preview_ok = true;
    session.last_reason = null;
    return true;
}

/// Apply keeps the current preview as one journal entry and clears the consumed
/// selection. Cancel reinstalls the exact base mesh and re-selects the original
/// stable welded index.
pub fn meshBevelEnd(commit: bool) bool {
    const active: *const z3d.BevelSession = if (z3d.g_bevel) |*session| session else return false;
    if (!active.last_preview_ok and active.last_mesh == null) {
        z3d.bevelFree();
        return false;
    }
    var session = z3d.g_bevel orelse return false;
    var ok = true;
    if (commit and session.last_preview_ok) {
        z3d.journalCommit(&session.snap);
        const face_parts: ?[]const u32 = if (session.last_face_part) |parts|
            parts
        else if (session.base_face_part) |parts|
            parts
        else
            null;
        if (face_parts) |parts| z3d.renormalizePartRanges(parts, session.part_count);
        if (session.last_mesh) |*mesh| {
            if (mesh.lower()) |lowered_value| {
                var lowered = lowered_value;
                defer lowered.deinit();
                z3d.adoptIndexedEditMesh(mesh, &lowered);
            } else |_| {}
        }
        if (session.kind == .face_polygon and session.last_center_triangle != null) {
            mesh_edit.setMode(.face);
            mesh_edit.clearSelection();
            _ = mesh_edit.selectFaceByIndex(session.last_center_triangle.?, false);
        } else {
            mesh_edit.setMode(session.original_mode);
            mesh_edit.clearSelection();
        }
    } else {
        const groups_arg: ?[]const u32 = if (session.base_groups) |groups| groups else null;
        if (session.base_mesh.lower()) |lowered_value| {
            var lowered = lowered_value;
            defer lowered.deinit();
            ok = z3d.lcInstallLowered(
                lowered.positions,
                lowered.uvs,
                lowered.tri_count,
                groups_arg,
                lowered.materials,
                lowered.semantic_regions,
                lowered.semantic_instances,
                session.base_colors,
                z3d.flattenedLogicalRows(lowered.triangle_vertices),
                @intCast(session.base_mesh.vertices.items.len),
            );
        } else |_| {
            ok = false;
        }
        if (ok) {
            if (session.base_mesh.clone()) |restored_value| {
                var restored = restored_value;
                defer restored.deinit();
                if (restored.lower()) |lowered_value| {
                    var lowered = lowered_value;
                    defer lowered.deinit();
                    z3d.adoptIndexedEditMesh(&restored, &lowered);
                } else |_| {}
            } else |_| {}
            z3d.g_paint_layout_stale = session.base_paint_layout_stale;
            mesh_edit.setMode(session.original_mode);
            if (session.original_mode == .vertex) {
                _ = mesh_edit.selectVertexByIndex(session.selection_index, false);
            } else if (session.original_mode == .face) {
                _ = mesh_edit.selectFaceByIndex(session.selection_index, false);
            } else if (session.boundary_selection) |selected_edges| {
                var first = true;
                for (selected_edges) |selected_edge| {
                    var edge_index: u32 = 0;
                    while (edge_index < mesh_edit.edgeCount()) : (edge_index += 1) {
                        const endpoints = mesh_edit.edgeEndpointsPub(edge_index);
                        const same = (endpoints[0] == selected_edge[0] and endpoints[1] == selected_edge[1]) or
                            (endpoints[0] == selected_edge[1] and endpoints[1] == selected_edge[0]);
                        if (!same) continue;
                        if (mesh_edit.selectEdgeByIndex(edge_index, !first)) first = false;
                        break;
                    }
                }
            } else {
                _ = mesh_edit.selectEdgeByIndex(session.selection_index, false);
            }
        }
        z3d.journalDiscard(&session.snap);
    }
    session.base_mesh.deinit();
    if (session.last_mesh) |*mesh| mesh.deinit();
    if (session.base_groups) |groups| std.heap.c_allocator.free(groups);
    std.heap.c_allocator.free(session.base_colors);
    if (session.base_face_part) |parts| std.heap.c_allocator.free(parts);
    if (session.last_face_part) |parts| std.heap.c_allocator.free(parts);
    if (session.boundary_loop) |loop| std.heap.c_allocator.free(loop);
    if (session.boundary_selection) |edges| std.heap.c_allocator.free(edges);
    if (session.polygon_faces) |faces| std.heap.c_allocator.free(faces);
    z3d.journalDiscard(&session.snap);
    z3d.g_bevel = null;
    return ok;
}

pub fn meshBevelFallbackReason() ?[]const u8 {
    const session: *const z3d.BevelSession = if (z3d.g_bevel) |*active| active else return null;
    return session.last_reason;
}
